{"file_path":"src/parse.js","content":"/**
 * The parser for the configuration document. It turns the lines of the
 * document into a tree of nodes:
 *
 *   { kind: 'table',   map: Map<string, node>, defined: boolean }
 *   { kind: 'array',   items: node[], aot: boolean }
 *   { kind: 'string' | 'integer' | 'float' | 'boolean', value }
 */

import { ConfError } from './errors.js'

const BARE = /[A-Za-z0-9_-]/
const DIGITS = '[0-9]+(?:_[0-9]+)*'
const INTEGER = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT = new RegExp(`^[+-]?${DIGITS}(\\.${DIGITS})?([eE][+-]?${DIGITS})?$`)

function newTable(defined = false) {
  return { kind: 'table', map: new Map(), defined }
}

function joinPath(base, key) {
  return base === '' ? key : `${base}.${key}`
}

/** The parser of a single line. The index walks along the line text. */
class LineParser {
  constructor(text, line) {
    this.s = text
    this.i = 0
    this.line = line
  }

  fail(reason) {
    return new ConfError(this.line, reason)
  }

  atEnd() {
    return this.i >= this.s.length
  }

  /** A comment runs from an unquoted `#` or `;` to the end of the line. */
  atComment() {
    const c = this.s[this.i]
    return c === '#' || c === ';'
  }

  /** The line is over once its text or a comment start is reached. */
  done() {
    return this.atEnd() || this.atComment()
  }

  skipWs() {
    while (!this.atEnd() && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  // --- names -------------------------------------------------------------

  parseName() {
    const c = this.s[this.i]
    if (c === '"') return this.parseBasicString()
    if (c === "'") return this.parseLiteralString()
    const start = this.i
    while (!this.atEnd() && BARE.test(this.s[this.i])) this.i++
    if (this.i === start) throw this.fail('expected a name')
    return this.s.slice(start, this.i)
  }

  /** Names joined by `.`, with spaces and tabs allowed around each dot. */
  parseDottedName() {
    const parts = [this.parseName()]
    for (;;) {
      const save = this.i
      this.skipWs()
      if (!this.atEnd() && this.s[this.i] === '.') {
        this.i++
        this.skipWs()
        parts.push(this.parseName())
      } else {
        this.i = save
        return parts
      }
    }
  }

  // --- strings -----------------------------------------------------------

  parseBasicString() {
    this.i++
    let out = ''
    for (;;) {
      if (this.atEnd()) throw this.fail('unterminated string')
      const c = this.s[this.i]
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        this.i++
        if (this.atEnd()) throw this.fail('unterminated string')
        const e = this.s[this.i]
        if (e === '"') out += '"'
        else if (e === '\\') out += '\\'
        else if (e === 'n') out += '\n'
        else if (e === 't') out += '\t'
        else if (e === 'r') out += '\r'
        else if (e === '0') out += '\0'
        else if (e === 'u') {
          const hex = this.s.slice(this.i + 1, this.i + 5)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) throw this.fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          this.i += 4
        } else throw this.fail(`invalid escape \\${e}`)
        this.i++
      } else {
        out += c
        this.i++
      }
    }
  }

  parseLiteralString() {
    this.i++
    const start = this.i
    while (!this.atEnd() && this.s[this.i] !== "'") this.i++
    if (this.atEnd()) throw this.fail('unterminated string')
    const out = this.s.slice(start, this.i)
    this.i++
    return out
  }

  // --- values ------------------------------------------------------------

  parseValue(path) {
    this.skipWs()
    if (this.done()) throw this.fail('expected a value')
    const c = this.s[this.i]
    if (c === ',' || c === ']' || c === '}') throw this.fail('expected a value')
    if (c === '"') return { kind: 'string', value: this.parseBasicString() }
    if (c === "'") return { kind: 'string', value: this.parseLiteralString() }
    if (c === '[') return this.parseArray(path)
    if (c === '{') return this.parseInlineTable(path)

    const start = this.i
    while (!this.atEnd()) {
      const d = this.s[this.i]
      if (d === ' ' || d === '\t' || d === ',' || d === ']' || d === '}') break
      this.i++
    }
    const text = this.s.slice(start, this.i)
    if (text === 'true') return { kind: 'boolean', value: true }
    if (text === 'false') return { kind: 'boolean', value: false }
    if (INTEGER.test(text)) return { kind: 'integer', value: Number(text.replace(/_/g, '')) }
    const float = FLOAT.exec(text)
    if (float && (float[1] !== undefined || float[2] !== undefined)) {
      return { kind: 'float', value: Number(text.replace(/_/g, '')) }
    }
    throw this.fail(`invalid value ${text}`)
  }

  parseArray(path) {
    this.i++
    const items = []
    for (;;) {
      this.skipWs()
      if (this.done()) throw this.fail('unterminated array')
      if (this.s[this.i] === ']') {
        this.i++
        return { kind: 'array', items, aot: false }
      }
      items.push(this.parseValue(`${path}[${items.length}]`))
      this.skipWs()
      if (!this.done() && this.s[this.i] === ',') {
        this.i++
        continue
      }
      if (!this.done() && this.s[this.i] === ']') {
        this.i++
        return { kind: 'array', items, aot: false }
      }
      throw this.fail('unterminated array')
    }
  }

  parseInlineTable(path) {
    this.i++
    const table = newTable()
    this.skipWs()
    if (!this.atEnd() && this.s[this.i] === '}') {
      this.i++
      return table
    }
    for (;;) {
      this.skipWs()
      if (this.done()) throw this.fail('unterminated inline table')
      const names = this.parseDottedName()
      this.skipWs()
      if (this.atEnd() || this.s[this.i] !== '=') throw this.fail('expected = in an inline table')
      this.i++
      const value = this.parseValue(names.reduce(joinPath, path))
      this.assign(table, path, names, value)
      this.skipWs()
      if (!this.done() && this.s[this.i] === ',') {
        this.i++
        continue
      }
      if (!this.done() && this.s[this.i] === '}') {
        this.i++
        return table
      }
      throw this.fail('unterminated inline table')
    }
  }

  // --- assignment --------------------------------------------------------

  /** Walks the dots from `table`, creating tables, and sets the last name. */
  assign(table, basePath, names, value) {
    let cur = table
    let path = basePath
    for (let n = 0; n < names.length - 1; n++) {
      path = joinPath(path, names[n])
      let next = cur.map.get(names[n])
      if (next === undefined) {
        next = newTable()
        cur.map.set(names[n], next)
      }
      if (next.kind === 'table') cur = next
      else if (next.kind === 'array' && next.aot && next.items.length > 0) {
        cur = next.items[next.items.length - 1]
      } else throw this.fail(`${path} is not a table`)
    }
    const last = names[names.length - 1]
    path = joinPath(path, last)
    if (cur.map.has(last)) throw this.fail(`key ${path} is defined twice`)
    cur.map.set(last, value)
  }
}

/** Parses the whole document and answers its root table. */
export function parse(lines) {
  const root = newTable(true)
  let current = root
  let currentPath = ''

  for (let n = 0; n < lines.length; n++) {
    const text = lines[n]
    const p = new LineParser(text, n + 1)
    p.skipWs()
    if (p.done()) continue

    if (p.s[p.i] === '[') {
      const header = parseHeader(p)
      const target = resolveHeader(p, root, header)
      current = target.table
      currentPath = target.path
      continue
    }

    const names = p.parseDottedName()
    p.skipWs()
    if (p.atEnd() || p.s[p.i] !== '=') throw p.fail('expected key = value')
    p.i++
    const value = p.parseValue(names.reduce(joinPath, currentPath))
    p.skipWs()
    if (!p.done()) throw p.fail('trailing text after a value')
    p.assign(current, currentPath, names, value)
  }

  return root
}

function parseHeader(p) {
  p.i++
  let aot = false
  if (!p.atEnd() && p.s[p.i] === '[') {
    aot = true
    p.i++
  }
  p.skipWs()
  const names = p.parseDottedName()
  p.skipWs()
  if (p.atEnd() || p.s[p.i] !== ']') throw p.fail('unterminated table header')
  p.i++
  if (aot) {
    if (p.atEnd() || p.s[p.i] !== ']') throw p.fail('unterminated table header')
    p.i++
  }
  p.skipWs()
  if (!p.done()) throw p.fail('trailing text after a table header')
  return { names, aot }
}

function resolveHeader(p, root, { names, aot }) {
  let cur = root
  let path = ''
  for (let n = 0; n < names.length - 1; n++) {
    path = joinPath(path, names[n])
    let next = cur.map.get(names[n])
    if (next === undefined) {
      next = newTable()
      cur.map.set(names[n], next)
    }
    if (next.kind === 'table') cur = next
    else if (next.kind === 'array' && next.aot && next.items.length > 0) {
      cur = next.items[next.items.length - 1]
    } else throw p.fail(`${path} is not a table`)
  }

  const last = names[names.length - 1]
  path = joinPath(path, last)
  let held = cur.map.get(last)

  if (!aot) {
    if (held === undefined) {
      held = newTable()
      cur.map.set(last, held)
    } else if (held.kind !== 'table') throw p.fail(`${path} is not a table`)
    else if (held.defined) throw p.fail(`table ${path} is defined twice`)
    held.defined = true
    return { table: held, path }
  }

  if (held === undefined) {
    held = { kind: 'array', items: [], aot: true }
    cur.map.set(last, held)
  } else if (held.kind !== 'array' || !held.aot) {
    throw p.fail(`${path} is not an array of tables`)
  }
  const fresh = newTable(true)
  held.items.push(fresh)
  return { table: fresh, path: `${path}[${held.items.length - 1}]` }
}
"}

