{"file_path":"src/render.js","content":"/** The two printings of a parsed document: canonical JSON and the key list. */

/** Compares two names by code point, ascending. */
function byCodePoint(a, b) {
  const x = [...a]
  const y = [...b]
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const c = x[i].codePointAt(0)
    const d = y[i].codePointAt(0)
    if (c !== d) return c - d
  }
  return x.length - y.length
}

function members(table) {
  return [...table.map.keys()].sort(byCodePoint).map((key) => [key, table.map.get(key)])
}

function render(node, indent) {
  const pad = ' '.repeat(indent)
  const inner = ' '.repeat(indent + 2)
  if (node.kind === 'table') {
    const entries = members(node)
    if (entries.length === 0) return '{}'
    const body = entries
      .map(([key, value]) => `${inner}${JSON.stringify(key)}: ${render(value, indent + 2)}`)
      .join(',\n')
    return `{\n${body}\n${pad}}`
  }
  if (node.kind === 'array') {
    if (node.items.length === 0) return '[]'
    const body = node.items.map((item) => `${inner}${render(item, indent + 2)}`).join(',\n')
    return `[\n${body}\n${pad}]`
  }
  return JSON.stringify(node.value)
}

/** The document as JSON indented by two spaces, with a trailing newline. */
export function toJson(root) {
  return `${render(root, 0)}\n`
}

/** One line per node below the root, `<path> <type>`, depth first. */
export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.kind === 'table') {
      for (const [key, value] of members(node)) {
        const child = path === '' ? key : `${path}.${key}`
        lines.push(`${child} ${value.kind}`)
        walk(value, child)
      }
    } else if (node.kind === 'array') {
      node.items.forEach((item, index) => {
        const child = `${path}[${index}]`
        lines.push(`${child} ${item.kind}`)
        walk(item, child)
      })
    }
  }
  walk(root, '')
  return lines.map((line) => `${line}\n`).join('')
}
"}

