export function toJson(root) {
  return `${render(root, 0)}\n`
}

/** One line per node below the root, `<path> <type>`, depth first. */
export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.kind === 'table') {
      for (const [key, value] of members(node)) {
