{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'node:fs'
import { ConfError } from './errors.js'
import { parse } from './parse.js'
import { toJson, toKeys } from './render.js'

function readInput() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  if (argv.length !== 1 || (argv[0] !== 'json' && argv[0] !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    return 2
  }

  const text = readInput()
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let out
  try {
    const root = parse(lines)
    out = argv[0] === 'json' ? toJson(root) : toKeys(root)
  } catch (error) {
    if (!(error instanceof ConfError)) throw error
    process.stderr.write(`error: line ${error.line}: ${error.reason}\n`)
    return 2
  }

  process.stdout.write(out)
  return 0
}

process.exitCode = main(process.argv.slice(2))
"}

